package com.paitrick.blog.tag.repository; import com.paitrick.blog.tag.domain.Tag; import org.apache.ibatis.annotations.*; import java.util.*; @Mapper public interface TagMapper{@Select("select * from tag order by name") List<Tag> all();@Select("select * from tag where id=#{id}") Tag byId(long id);@Insert("insert into tag(name,slug) values(#{name},#{slug})") @Options(useGeneratedKeys=true,keyProperty="id") int insert(Tag t);@Update("update tag set name=#{name},slug=#{slug} where id=#{id}") int update(Tag t);@Delete("delete from tag where id=#{id}") int delete(long id);}
